PreToolUse.bash:
# Hard stop on repeated tool calls - prevents infinite loops
node -e '
const fs=require("fs");
try{
const input=JSON.parse(fs.readFileSync(0,"utf8"));
const cmd=(input.toolName||input.command||"unknown").toString();
const sf="/tmp/.copilot-loop-check.json";
let last=null;
try{last=JSON.parse(fs.readFileSync(sf,"utf8"));}catch(e){}
if(last&&last.cmd===cmd){
console.log(JSON.stringify({block:true,reason:"BLOCKED: Repeated identical tool call detected - this prevents infinite loops"}));
process.exit(0);
}
fs.writeFileSync(sf,JSON.stringify({cmd:cmd}));
}catch(e){console.log("{}");}'

# Block excessive search calls - delegate to Data instead
node -e '
const fs=require("fs");
try{
const sf="/tmp/.copilot-search-count.json";
let c=0;
try{c=JSON.parse(fs.readFileSync(sf,"utf8")).count||0;}catch(e){}
c++;
fs.writeFileSync(sf,JSON.stringify({count:c}));
if(c>=3){
console.log(JSON.stringify({block:true,reason:"BLOCKED: Search loop detected (>3 consecutive searches). Delegate library/API research to Data agent instead of searching source code."}));
process.exit(0);
}
}catch(e){console.log("{}");}'

PostToolUse.bash:
# Reset search counter on successful non-search tool use
node -e '
const fs=require("fs");
try{
const input=JSON.parse(fs.readFileSync(0,"utf8"));
const cmd=(input.toolName||input.command||"unknown").toString();
if(!cmd.includes("search")&&!cmd.includes("grep")){
try{fs.unlinkSync("/tmp/.copilot-search-count.json");}catch(e){}
console.log(JSON.stringify({additionalContext:""}));
}else{console.log("{}");}
}catch(e){console.log("{}");}'
